async function readLogo(file){if(!file?.size)return null;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>5*1024*1024)throw Error('Choose a PNG, JPG or WebP logo up to 5 MB.');const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode();if(!img.naturalWidth||!img.naturalHeight||img.naturalWidth*img.naturalHeight>40000000)throw Error('Logo dimensions are too large.');const canvas=document.createElement('canvas');canvas.width=128;canvas.height=128;const ctx=canvas.getContext('2d');const scale=Math.min(128/img.naturalWidth,128/img.naturalHeight);const w=Math.round(img.naturalWidth*scale),h=Math.round(img.naturalHeight*scale);ctx.drawImage(img,Math.floor((128-w)/2),Math.floor((128-h)/2),w,h);const data=canvas.toDataURL('image/webp',.88);if(!validLogo(data))throw Error('Unable to optimize the logo. Try a smaller image.');return data}catch(err){throw Error(err.message||'Unable to read logo image.')}finally{URL.revokeObjectURL(url)}}
