function gameOverviewPanel(){
 const rows=gamePortfolioStats,highestSales=Math.max(0,...rows.map(g=>Number(g.day_deposits)||0)),highestWin=Math.max(0,...rows.map(g=>Number(g.day_gross_cashouts)||0));
 const liveCards=rows.map(g=>{const live=backendTicker.find(t=>t.game_id===g.game_id),sold=highestSales>0&&Number(g.day_deposits)===highestSales,won=highestWin>0&&Number(g.day_gross_cashouts)===highestWin;
 return '<section class="card" style="border:'+(won?'2px solid #ef4444':'1px solid #334155')+';min-width:0"><div class="row">'+gamePortfolioLink(g.game_id,g.game_name)+'</div><div style="display:flex;gap:6px;flex-wrap:wrap;margin:6px 0">'+(sold?gameTag('Most Selling','#4ade80'):'')+(won?gameTag('Most Player Won','#f87171'):'')+'</div><div class="metric-label">Live available backend points</div><div class="metric-value">'+gameAvailable(g)+'</div><p class="muted">Today IN: <b>'+money(g.day_deposits)+'</b> · Points loaded: '+fmt(g.day_points_loaded)+'</p><p class="muted">Today player cash-outs: <b style="color:'+(won?'#f87171':'inherit')+'">'+money(g.day_gross_cashouts)+'</b> · '+fmt(g.day_winning_players)+' players</p><p class="muted">Cash-out / deposits: '+gameWinRatio(g)+'</p>'+(!live||live.estimated_available==null?openingBalanceForm(g):'<p class="muted">Last actual: '+fmt(live.starting_balance)+' pts · '+date(live.last_closing_at)+'</p>')+'</section>'}).join('');
 const totalIn=sum(rows,g=>g.day_deposits),totalOut=sum(rows,g=>g.day_gross_cashouts),ratio=totalIn>0?fmt(totalOut/totalIn*100)+'%':(totalOut>0?'No deposits':'—');
 return panel('Live Games Overview · Owner','<p class="muted">Current business day: '+(rows.length?gamePeriodDate(rows[0].day_start)+' — '+gamePeriodDate(rows[0].day_end):'No games configured')+' · '+esc(workspace.closing_timezone||'UTC')+'. Most Selling = highest actual deposits; Most Player Won = highest gross cash-outs today (red). Rankings exclude zero activity. Cash-out/deposit ratio is an operational measure, not game win probability; 30% reference / 40% example range.</p><div class="grid">'+metric('Today Platform IN',money(totalIn))+metric('Today Gross Cash Outs',money(totalOut))+metric('Today Cash-Out / IN',ratio)+'</div><div class="grid" style="margin-top:12px">'+(liveCards||'<p class="muted">Add a game in Settings to begin.</p>')+'</div><p class="muted">Live points = last actual + reloads + redeemed points − loaded points. Set actual opening balances from the game backend; prior activity is already included in that measured balance. Click a game name to view its portfolio.</p>');
}
function gamePlayerPortfolioRows(gameId){
 const map=new Map(),overall=new Map();function row(id){if(!map.has(id))map.set(id,{id,deposits:0,points:0,bonus:0,loads:0,cashouts:0,gross:0,net:0,returned:0});return map.get(id)}
 for(const l of loads){const paid=Number(l.payment)>0;if(paid)overall.set(l.player_id,(overall.get(l.player_id)||0)+1);if(l.game_id!==gameId)continue;const r=row(l.player_id);r.deposits+=Number(l.payment||0);r.points+=Number(l.points||0);r.bonus+=Math.max(0,Number(l.points||0)-Number(l.payment||0));r.loads+=paid?1:0}
 for(const c of cashouts){if(c.game_id!==gameId)continue;const r=row(c.player_id);r.cashouts++;r.gross+=Number(c.gross_amount||0);r.net+=Number(c.net_paid||0);r.returned+=Number(c.points||0)}
 return [...map.values()].sort((a,b)=>b.deposits-a.deposits||playerName(a.id).localeCompare(playerName(b.id))).map(r=>[esc(playerName(r.id)),r.loads>5?gameTag('Regular on game','#86efac'):(overall.get(r.id)||0)>5?gameTag('Regular on platform','#86efac'):(r.loads===0?'No paid load':'Non-regular'),fmt(r.loads),money(r.deposits),fmt(r.points),fmt(r.bonus),fmt(r.cashouts),money(r.gross),money(r.net),fmt(r.returned)]);
}
function gamePortfolioPage(g){
 const live=backendTicker.find(t=>t.game_id===g.game_id);
 return '<button type="button" class="ghost" data-action="back-game-overview">← Back to Games Overview</button>'+panel(gameLabel(g.game_id,g.game_name)+' · Game Portfolio','<p class="muted">Live balances and all recorded transactions on this game. Player cash-outs are gross amounts before processing fees; net payouts are shown separately.</p><div class="grid">'+metric('Live Available Points',gameAvailable(g))+metric('Total Deposits (IN)',money(g.total_deposits))+metric('Total Points Loaded',fmt(g.total_points_loaded))+metric('Total Gross Cash Outs',money(g.total_gross_cashouts))+metric('Total Net Player Payouts',money(g.total_net_cashouts))+metric('Total Redeemed Points',fmt(g.total_points_redeemed))+metric('Total Extra Bonus Points',fmt(g.total_bonus_points))+metric('Paid Deposit Tickets',fmt(g.total_deposit_count))+metric('Cash-Out Tickets',fmt(g.total_cashout_count))+metric('Unique Players With Activity',fmt(g.total_players))+metric('Depositing Players',fmt(g.total_depositors))+metric('Regular Players (platform 6+)',fmt(g.regular_players))+metric('Regular On This Game (6+)',fmt(g.game_regular_players))+metric('Lifetime Cash-Out / IN',g.total_win_ratio==null?'—':fmt(g.total_win_ratio)+'%')+'</div>'+(!live||live.estimated_available==null?openingBalanceForm(g):'<p class="muted">Actual opening/last closing: '+fmt(live.starting_balance)+' pts · '+date(live.last_closing_at)+'</p>'))+panel('Current Business Day','<p class="muted">'+gamePeriodDate(g.day_start)+' — '+gamePeriodDate(g.day_end)+'</p><div class="grid">'+metric('Deposits',money(g.day_deposits))+metric('Points Loaded',fmt(g.day_points_loaded))+metric('Gross Cash Outs',money(g.day_gross_cashouts))+metric('Points Redeemed',fmt(g.day_points_redeemed))+metric('Players Who Cashed Out',fmt(g.day_winning_players))+metric('Paid Deposits',fmt(g.day_deposit_count))+metric('Cash-Out / IN',gameWinRatio(g))+'</div>')+panel('Player Portfolio · All Time','<p class="muted">Regular = at least 6 successful paid Load tickets. Platform and game-specific status shown separately. Players with no recorded activity on this game cannot be assigned to it.</p>'+tbl(['Player','Regular Status','Deposit Tickets','Total IN','Points Loaded','Extra Bonus','Cash-Out Tickets','Gross Cash Outs','Net Paid','Points Redeemed'],gamePlayerPortfolioRows(g.game_id)));
}
function backendTickerTable(){
 return '<p class="muted">Estimated balance = last recorded actual + reloads + cash-out point credits − loaded points since that closing. Verify against the real backend before finalizing.</p>'+
 tbl(['Backend','Last Actual','Reloads','Loads','Cash-Out Credits','Estimated Now','Last Closing','Alerts'],
 backendTicker.map(x=>[gamePortfolioLink(x.game_id,x.game_name),x.starting_balance===null?'Baseline needed':fmt(x.starting_balance),fmt(x.points_reloaded),fmt(x.points_loaded),fmt(x.cashout_credit),
 x.estimated_available===null?'—':fmt(x.estimated_available),date(x.last_closing_at),x.needs_review?'Review required':'—']));
}

function loadTable(rows){return tbl(['Date','Player','Backend','Received','Points Loaded','Extra Bonus','Worker'],rows.map(l=>[date(l.created_at),esc(playerName(l.player_id)),gameLabel(l.game_id),money(l.payment),fmt(l.points),fmt(Number(l.points)-Number(l.payment)),esc(workerName(l.created_by))]))}

function walletHistoryRows(playerIds){
 const ids=playerIds?new Set(playerIds):null;
 const items=[
  ...loads.filter(x=>!ids||ids.has(x.player_id)).map(l=>({at:l.created_at,id:l.id,pid:l.player_id,kind:'Load',backend:l.game_id,provider:l.provider_id,amount:l.payment,points:l.points,bonus:Number(l.points)-Number(l.payment),note:l.note||'',worker:l.created_by,status:l.correction_reason?'Corrected':'Recorded'})),
  ...cashouts.filter(x=>!ids||ids.has(x.player_id)).map(x=>({at:x.created_at,id:x.id,pid:x.player_id,kind:'Cash Out',backend:x.game_id,provider:x.provider_id,amount:x.net_paid,points:x.points,bonus:null,note:x.note||'',worker:x.created_by,status:x.review_status}))
 ].sort((a,b)=>b.at.localeCompare(a.at));
 return items.map(x=>[date(x.at),esc(playerName(x.pid)),esc(x.kind),gameLabel(x.backend),providerLabel(x.provider),money(x.amount),fmt(x.points),x.bonus===null?'—':fmt(x.bonus),esc(x.status),esc(x.note),esc(workerName(x.worker))])
}
function walletSummaryRows(collection){
 return collection.map(p=>{
 const ls=loads.filter(l=>l.player_id===p.id),cs=cashouts.filter(x=>x.player_id===p.id);
 const newBadge=Date.now()-new Date(p.created_at).getTime()<48*3600000?' <span class="pill">New</span>':'';
 return [
   esc(p.name)+newBadge+(role==='owner'&&ls.filter(l=>Number(l.payment)>0).length>5?' <span class="pill" style="color:#86efac">Regular</span>':''),
   '<strong>'+fmt(walletBonusTotals.get(p.id)||0)+' pts</strong>',
   money(sum(ls,l=>l.payment)),
   fmt(sum(ls,l=>l.points)),
   fmt(sum(cs,x=>x.points)),
   ls.length,
   cs.length,
   '<code title="Full player ID: '+esc(p.id)+'">'+esc(p.id.slice(0,8))+'</code>'
 ];
 })}
