if(form==='review-load-correction'){if(!manager())throw Error('Manager only');const r=await sb.rpc('review_load_correction',{p_request:d.request_id,p_approve:submitter?.value==='approve',p_review_note:d.note});if(r.error)throw r.error;await completeSave('Correction Review Saved Successfully',submitter?.value==='approve'?'Correction approved.':'Correction rejected.');return}
