if(form==='reconcile'){if(!manager())throw Error('Manager/Owner only');const x=await sb.rpc('record_payment_reconciliation',{p_provider:d.provider_id,p_start:new Date(d.start).toISOString(),p_end:new Date(d.end).toISOString(),p_actual:Number(d.actual),p_note:d.note});if(x.error)throw x.error;await completeSave('Reconciliation Submitted Successfully','Provider reconciliation recorded.');return}
