if(form==='game-opening-balance'){if(role!=='owner')throw Error('Owner only');const r=await sb.rpc('record_game_opening_balance',{p_game:d.game_id,p_balance:Number(d.balance)});if(r.error)throw r.error;await completeSave('Opening Balance Saved Successfully','Live point tracking is now active.');return}
 if(form==='cashout-rules'){if(role!=='owner')throw Error('Owner only');const result=await sb.rpc('update_platform_cashout_rules',{p_workspace:workspace.id,p_min_multiplier:Number(d.min_multiplier),p_max_points:Number(d.max_points),p_fee_rate:0,p_fee_fixed:0,p_fee_bearer:d.fee_bearer});if(result.error)throw result.error;await completeSave('Platform Rules Saved Successfully','Cash-out rules have been updated.');return}
if(['provider','receive-merchant','cashout-merchant-bulk'].includes(form)){const cash=form==='cashout-merchant-bulk';if(cash&&role!=='owner')throw Error('Owner only');const methods=new FormData(f).getAll('methods').map(String);if(d.custom_method?.trim())methods.push(d.custom_method.trim());if(!methods.length)throw Error('Select at least one payment method or enter a custom method.');const logo=await readLogo(d.brand_logo);const r=await sb.rpc('save_provider_methods_with_logo',{p_workspace:workspace.id,p_company:d.company,p_methods:methods,p_direction:cash?'cashout':'receive',p_rate:Number(cash?d.cashout_rate:d.rate),p_fixed:Number(cash?d.cashout_fixed:d.fixed_fee),p_logo:logo});if(r.error)throw r.error;await completeSave('Payment Methods Saved Successfully',r.data+' payment method(s) saved for '+d.company+'.');return}
 if(form==='cashout-merchant'){if(role!=='owner')throw Error('Owner only');const r=await sb.rpc('save_cashout_merchant',{p_workspace:workspace.id,p_provider:d.provider_id||null,p_company:d.company||'',p_method:d.method||'',p_rate:Number(d.cashout_rate),p_fixed:Number(d.cashout_fixed)});if(r.error)throw r.error;await completeSave('Cash-Out Fee Saved Successfully','Merchant cash-out fee has been updated.');return}
 if(form==='cashout'){const r=await sb.rpc('record_cashout',{p_player:d.player_id,p_game:d.game_id,p_provider:d.provider_id,p_points:Number(d.points),p_gross:Number(d.gross),p_note:d.note||''});if(r.error)throw r.error;await completeSave('Cash-Out Submitted Successfully',()=>{const ticket=cashouts.find(x=>x.id===r.data);return ticket?'Player receives '+money(ticket.net_paid)+' · Processor debit '+money(ticket.processor_debit)+' · Processing fee '+money(ticket.processing_fee)+(ticket.review_status==='review_required'?' · Owner review required.':''):'Your cash-out ticket has been recorded.'});return}
if(form==='correct-cashout'){if(!manager())throw Error('Manager/Owner only');const r=await sb.rpc('correct_cashout',{p_cashout:d.cashout_id,p_points:Number(d.points),p_gross:Number(d.gross),p_reason:d.reason});if(r.error)throw r.error;await completeSave('Cash-Out Correction Submitted Successfully','Correction audited; Owner review required.');return}
if(form==='approve-cashout'){if(role!=='owner')throw Error('Owner only');const r=await sb.rpc('approve_cashout',{p_cashout:d.cashout_id,p_reason:d.reason});if(r.error)throw r.error;await completeSave('Cash-Out Approved Successfully','Owner approval recorded.');return}
if(form==='closing'){const r=await sb.rpc('finalize_backend_closing',{p_game:d.game_id,p_balance:Number(d.balance),p_note:d.note});if(r.error)throw r.error;await completeSave('Backend Closing Submitted Successfully','The closing balance has been recorded.');return}
let row={workspace_id:workspace.id},tableName=form;
if(form==='player'){const normalized=String(d.name||'').trim().replace(/\s+/g,' ').toLowerCase();if(!normalized)throw Error('Player name is required.');if(players.some(p=>String(p.name||'').trim().replace(/\s+/g,' ').toLowerCase()===normalized))throw Error('Duplicate player name/ID. Open the existing wallet instead.');Object.assign(row,{name:d.name.trim(),created_by:user.id});tableName='players';}
